package bo.com.ganadero.animales.infrastructure; import bo.com.ganadero.animales.domain.*; import bo.com.ganadero.shared.db.Rows; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Repository; import java.util.*;
@Repository class JdbcCategoriaAnimalRepository implements CategoriaAnimalRepository {private final JdbcClient jdbc;JdbcCategoriaAnimalRepository(JdbcClient j){jdbc=j;}public List<CategoriaAnimal> findActive(UUID e){return jdbc.sql("select * from categoria_animal where activo order by edad_min_meses,nombre").query(this::map).list();}public Optional<CategoriaAnimal> findById(UUID id,UUID e){return jdbc.sql("select * from categoria_animal where id=:id and activo").param("id",id.toString()).query(this::map).optional();}private CategoriaAnimal map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new CategoriaAnimal(Rows.uuid(r,"id"),null,r.getString("codigo"),r.getString("nombre"),r.getString("sexo_aplicable"),(Integer)r.getObject("edad_min_meses"),(Integer)r.getObject("edad_max_meses"),r.getString("descripcion"),r.getBoolean("activo"));}}
